import math

def check_expression(n):
    """Checks if the expression 3*((n+2)! + 1) / (2n - 1) is an integer for a given n."""
    # Check for division by zero (only if 2n-1 = 0, i.e., n=0.5, which is not in our range)
    D = 2 * n - 1
    if D == 0:
        return False

    try:
        # Calculate (n+2)!
        factorial_term = math.factorial(n + 2)

        # Calculate the numerator N = 3 * ((n+2)! + 1)
        N = 3 * (factorial_term + 1)

        # Check for divisibility
        if N % D == 0:
            return True
        else:
            return False
    except OverflowError:
        # Should not happen for n <= 30, but good practice
        return False

solutions = []
# Check from n=0 up to n=30 inclusive
for n in range(31):
    if check_expression(n):
        solutions.append(n)

print(f"Solutions found up to n=30: {solutions}")
